// SPDX-License-Identifier: MIT
pragma solidity ^0.8.7;
import "./IBEP20.sol";
import {Advert,Shared} from "./Advert.sol";

contract Trade{

    struct trade{
        string advertId;
        address payable buyer;
        uint amount;
    }
    address admin;
    Advert A;

    mapping(string=>trade) public Trades;

    constructor (address _admin,address payable _advert){
        admin = _admin;
        A = Advert(_advert);
    }

    function createTrade(string memory _tradeId, string memory _advertId,address payable _buyer,uint _amount) external {
        // Shared.advert memory adv = (A.Adverts(_advertId));
        uint advertBalance = A.getBalance(_advertId);
        require(_amount <= advertBalance,"insufficient balance to initiate trade");
        Trades[_tradeId] = trade(_advertId,_buyer,_amount);
    }

   receive() external payable{}

    function buy(string memory _tradeId) external{
        trade memory T = Trades[_tradeId];
        // could've done checks for msg.sender to be buyer but contract deployer will make the transfer
        require(msg.sender == admin,"unauthorized to make transfer");
        A.transferAsset(T.advertId,T.buyer,T.amount);
    }

}
